import itertools

def find_vectors(n, target_sum):
    res = []
    # We search for vectors whose sum of squares is target_sum
    # a_i^2 <= target_sum
    limit = int(target_sum**0.5)
    possible_vals = range(-limit, limit + 1)

    # This might be slow for n=4. Let's optimize.
    # Use a recursive search.
    def search(current_vec, current_sum, dim):
        if dim == n:
            if current_sum == target_sum:
                res.append(tuple(current_vec))
            return

        rem_sum = target_sum - current_sum
        # The remaining elements must satisfy sum of squares = rem_sum
        # So max value is sqrt(rem_sum)
        limit_i = int(rem_sum**0.5)
        for v in range(-limit_i, limit_i + 1):
            search(current_vec + [v], current_sum + v*v, dim + 1)

    search([], 0, 0)
    return res

def test_n(n, max_k):
    for k in range(1, max_k + 1):
        a_vectors = find_vectors(n, k*k)
        b_vectors = find_vectors(n, 7*k*k)
        for a in a_vectors:
            for b in b_vectors:
                if sum(ai * bi for ai, bi in zip(a, b)) == 0:
                    return True, k, a, b
    return False, None, None, None

print(test_n(4, 10))
